"""`generate branch-tests` counts the screens it generated, not the ones it skipped.

A consumer named one screen whose `metadata.platforms` left out web and ran
the MCP tool with its default platform. The run printed "Skipped …", then
"1 screen(s) generated by jsonui-test 2.5.10.", exited 0 (`success: true`)
and wrote nothing — the 0 files showed only in `git status`.

Pinned here:
- the count says generated and skipped apart, in both the toolchain line and
  the line of a run where some screens failed;
- naming one screen that is then skipped exits 1, generating or checking,
  for both ways a screen is skipped (its platforms leave this platform out;
  every branch it declares belongs to another platform) — and the retiring
  of a test generated there before still happens and is said;
- a whole-project scan that skips screens keeps exit 0: skipping some
  screens there is ordinary, and every consumer gate runs this form.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).parent.parent))
sys.path.insert(0, str(Path(__file__).parent))

from jsonui_test_cli.cli import cmd_generate_branch_tests

from test_branch_tests_generator import BASIC, _project, _write

SPECS = "docs/specs"
GENERATED = "tests/unit/generated"


class _Args:
    def __init__(self, screen=None, **kw):
        self.screen = screen
        self.spec = None
        self.check = kw.pop("check", False)
        self.platform = kw.pop("platform", "web")
        self.out_dir = GENERATED
        self.harness_dir = "tests/unit/branch-harness"
        self.mocks_dir = "tests/mocks"
        self.package = None
        self.module = None
        for key, value in kw.items():
            setattr(self, key, value)


def _screen(root: Path, name: str, kind: str) -> None:
    """Add a screen beside checkout: 'excluded' (no web in its platforms),
    'scoped' (its only branch is for ios), 'failing' (a missing scenario),
    or 'applicable'."""
    spec = json.loads((root / SPECS / "checkout.spec.json").read_text())
    spec["metadata"]["name"] = name.title()
    spec["metadata"]["layoutFile"] = name
    if kind == "excluded":
        spec["metadata"]["platforms"] = ["ios", "android"]
    elif kind == "scoped":
        spec["branchContracts"] = {"methods": {"onConfirmTap": {"branches": [
            {"when": {"data.isAgreed": False}, "then": {"api": "none"},
             "platforms": ["ios"]}]}}}
    elif kind == "failing":
        spec["branchContracts"] = {"methods": {"onConfirmTap": {"branches": [
            {"when": {"api.createOrder": "no_such_scenario"},
             "then": {"data.screenState": "x"}}]}}}
    _write(root / SPECS / f"{name}.spec.json", spec)


@pytest.fixture
def project(tmp_path, monkeypatch):
    root = _project(tmp_path, BASIC)
    _write(root / "jui.config.json", {"spec_directory": SPECS,
                                      "platforms": ["ios", "android", "web"]})
    monkeypatch.chdir(root)
    return root


def _generated(root: Path) -> list[Path]:
    out = root / GENERATED
    return sorted(out.rglob("*.branches.test.ts")) if out.exists() else []


def _run(capsys, *args, **kw):
    rc = cmd_generate_branch_tests(_Args(*args, **kw))
    out = capsys.readouterr()
    return rc, out.out, out.err


class TestANamedScreenThatIsSkipped:
    @pytest.mark.parametrize("kind", ["excluded", "scoped"])
    def test_generating_it_says_0_generated_and_fails(self, project, capsys, kind):
        _screen(project, "passkey", kind)

        rc, out, err = _run(capsys, "passkey")

        assert rc == 1, out + err
        assert "0 screen(s) generated by jsonui-test" in out
        assert "1 skipped" in out
        assert "1 screen(s) generated" not in out
        assert "'passkey' was skipped on web" in err
        assert "--platform" in err
        assert not (project / GENERATED / "passkey.branches.test.ts").exists()

    @pytest.mark.parametrize("kind", ["excluded", "scoped"])
    def test_checking_it_fails_too(self, project, capsys, kind):
        _screen(project, "passkey", kind)

        rc, out, err = _run(capsys, "passkey", check=True)

        assert rc == 1, out + err
        assert "nothing was checked" in err

    def test_a_test_generated_there_before_is_still_retired_and_said(self, project, capsys):
        rc, _, _ = _run(capsys, "checkout")
        assert rc == 0
        before = project / GENERATED / "checkout.branches.test.ts"
        assert before.exists()
        spec_path = project / SPECS / "checkout.spec.json"
        spec = json.loads(spec_path.read_text())
        spec["metadata"]["platforms"] = ["ios"]
        spec_path.write_text(json.dumps(spec))

        rc, out, err = _run(capsys, "checkout")

        assert rc == 1, out + err
        assert not before.exists()
        assert "removed" in out and "checkout.branches.test.ts" in out

    def test_a_named_screen_for_this_platform_still_passes(self, project, capsys):
        rc, out, err = _run(capsys, "checkout")

        assert rc == 0, out + err
        assert "1 screen(s) generated by jsonui-test" in out
        assert "skipped" not in out.split("screen(s) generated")[-1]
        assert _generated(project)


class TestAWholeProjectScan:
    def test_skipped_screens_are_counted_apart_and_exit_0(self, project, capsys):
        _screen(project, "passkey", "excluded")
        _screen(project, "scoped", "scoped")

        rc, out, err = _run(capsys)

        assert rc == 0, out + err
        assert "1 screen(s) generated by jsonui-test" in out
        assert "2 skipped" in out
        assert [p.name for p in _generated(project)] == ["checkout.branches.test.ts"]

    def test_every_screen_skipped_is_0_generated_and_exit_0(self, project, capsys):
        _screen(project, "passkey", "excluded")
        (project / SPECS / "checkout.spec.json").unlink()

        rc, out, err = _run(capsys)

        assert rc == 0, out + err
        assert "0 screen(s) generated by jsonui-test" in out
        assert not _generated(project)

    def test_a_run_with_failures_counts_skipped_apart(self, project, capsys):
        _screen(project, "passkey", "excluded")
        _screen(project, "broken", "failing")

        rc, out, err = _run(capsys)

        assert rc == 1
        assert "Generated 1 screen(s), 1 skipped; 1 failed." in err
        assert "1 screen(s) generated by jsonui-test" in out
